<?php $sectionMetrics = ['Total de prendas' => count($prendas), 'Disponibles' => count(array_filter($prendas,static fn($p)=>$p['estado']==='Activo')), 'Inactivas' => count(array_filter($prendas,static fn($p)=>$p['estado']==='Inactivo'))]; ?>
<div class="module-metrics" aria-label="Indicadores de Prendas del catálogo">
<?php foreach($sectionMetrics as $label=>$count): ?><div class="module-metric"><span><?= h($label) ?></span><strong><?= (int)$count ?></strong></div><?php endforeach; ?>
</div>
<section class="management-grid section-management" aria-label="Prendas del catálogo">
<article class="dash-panel management" id="prendas" data-module="prendas"><div class="manage-title"><div class="manage-icon"><?= admIcon('shirt') ?></div><div><h2>Gestión de prendas</h2><small>Administra las prendas del catálogo</small></div><button class="primary mini" data-new="prendas"><?= admIcon('plus') ?> Nueva prenda</button></div>
<div class="manage-filters"><label class="search-field"><?= admIcon('search') ?><input data-search type="search" placeholder="Buscar prenda..."></label><select data-filter aria-label="Filtrar categoría"><option value="">Todas las categorías</option><?php foreach($categorias as $cat):?><option value="<?= h($cat['nombre']) ?>"><?= h($cat['nombre']) ?></option><?php endforeach; ?></select></div>
<div class="table-scroll"><table><thead><tr><th>ID</th><th>Imagen</th><th>Nombre</th><th>Categoría</th><th>Estado</th><th>Acciones</th></tr></thead><tbody><?php foreach($prendas as $r):?><tr data-searchable="<?= h($r['id'].' '.$r['nombre'].' '.$r['categoria'].' '.$r['estado']) ?>" data-filter-value="<?= h($r['categoria']) ?>"><td><?= (int)$r['id'] ?></td><td><?php if(garmentImage($r,$images)):?><img class="garment-thumb" src="<?= h(garmentImage($r,$images)) ?>" alt=""><?php else: ?><span class="empty-thumb"><?= admIcon('shirt') ?></span><?php endif; ?></td><td><?= h($r['nombre']) ?></td><td><?= h($r['categoria']) ?></td><td><?= stateBadge($r['estado']) ?></td><td class="actions"><?= makeEdit('prendas',$r) ?><?= stateButton('prendas',$r) ?></td></tr><?php endforeach; ?></tbody></table></div><div class="pagination"><span data-count></span><div data-pages></div></div></article>
</section>
